const data = $input.all()[0].json;

// 1. กราฟสัดส่วนประเภทการลา (Leave Types)
const byLeaveType = data?.byLeaveType || data?.byType || {};
const pieLabels = Object.keys(byLeaveType);
const pieDataValues = Object.values(byLeaveType);

const pieChartConfig = {
  type: 'doughnut',
  data: {
    labels: pieLabels.length > 0 ? pieLabels : ['ไม่มีข้อมูลการลา'],
    datasets: [{
      data: pieDataValues.length > 0 ? pieDataValues : [1],
      backgroundColor: pieLabels.length > 0 
        ? ['#4f46e5', '#06b6d4', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6'] 
        : ['#cbd5e1']
    }]
  },
  options: {
    title: { display: true, text: 'สัดส่วนประเภทการลา (Leave Types)' }
  }
};
const pieChartUrl = data?.pieChartUrl || ('https://quickchart.io/chart?c=' + encodeURIComponent(JSON.stringify(pieChartConfig)));

// 2. กราฟแสดงแนวโน้มการลา (Leave Trend - ข้อ 1.4.5.4)
const trend = data?.trend || {};
const trendLabels = Object.keys(trend);
const trendValues = Object.values(trend);

const trendChartConfig = {
  type: 'line',
  data: {
    labels: trendLabels.length > 0 ? trendLabels : ['ไม่มีข้อมูล'],
    datasets: [{
      label: 'จำนวนคำขอลา (รายการ)',
      data: trendValues.length > 0 ? trendValues : [0],
      borderColor: '#4f46e5',
      backgroundColor: 'rgba(79, 70, 229, 0.15)',
      fill: true,
      tension: 0.3,
      pointBackgroundColor: '#4f46e5'
    }]
  },
  options: {
    title: { display: true, text: 'แนวโน้มการลา (Leave Trend)' },
    scales: {
      yAxes: [{ ticks: { beginAtZero: true, stepSize: 1, precision: 0 } }]
    }
  }
};
const trendChartUrl = data?.trendChartUrl || ('https://quickchart.io/chart?c=' + encodeURIComponent(JSON.stringify(trendChartConfig)));

// 3. กราฟสถิติตามประเภทบุคลากร 5 ประเภท (Personnel Types - ข้อ 1.4.2)
const byPersonnelType = data?.byPersonnelType || {};
const pLabels = Object.keys(byPersonnelType);
const pValues = Object.values(byPersonnelType);

const personnelChartConfig = {
  type: 'bar',
  data: {
    labels: pLabels.length > 0 ? pLabels : ['ไม่มีข้อมูล'],
    datasets: [{
      label: 'คำขอลา (รายการ)',
      data: pValues.length > 0 ? pValues : [0],
      backgroundColor: ['#1d4ed8', '#0369a1', '#15803d', '#047857', '#b45309', '#6d28d9']
    }]
  },
  options: {
    title: { display: true, text: 'สถิติการลาแยกตามประเภทบุคลากร 5 ประเภท' },
    legend: { display: false },
    scales: {
      yAxes: [{ ticks: { beginAtZero: true, stepSize: 1, precision: 0 } }]
    }
  }
};
const personnelChartUrl = data?.personnelChartUrl || ('https://quickchart.io/chart?c=' + encodeURIComponent(JSON.stringify(personnelChartConfig)));

// 4. กราฟสถิติตามสาขา/แผนก
const byDepartment = data?.byDepartment || {};
const barLabels = Object.keys(byDepartment);
const barDataValues = Object.values(byDepartment);

const barChartConfig = {
  type: 'bar',
  data: {
    labels: barLabels.length > 0 ? barLabels : ['ไม่มีข้อมูล'],
    datasets: [{
      label: 'คำขอตามแผนก (รายการ)',
      data: barDataValues.length > 0 ? barDataValues : [0],
      backgroundColor: '#06b6d4'
    }]
  },
  options: {
    title: { display: true, text: 'สถิติการลาแยกตามสาขา/แผนก' },
    scales: {
      yAxes: [{ ticks: { beginAtZero: true, stepSize: 1, precision: 0 } }]
    }
  }
};
const barChartUrl = data?.barChartUrl || ('https://quickchart.io/chart?c=' + encodeURIComponent(JSON.stringify(barChartConfig)));

return {
  json: {
    ...data,
    pieChartUrl,
    trendChartUrl,
    personnelChartUrl,
    barChartUrl
  }
};

